{
  "tasks": [
    {
      "task_id": "T01",
      "title": "各城市岗位数量分布",
      "business_question": "不同城市的招聘数据中，岗位数量分别是多少？以探索地域分布差异。",
      "priority": "P0",
      "priority_reason": "删除此任务将无法回答核心需求C01中关于主要分布（特别是地域维度）的问题，是探索性分析的基础。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "job_count"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "sort",
          "params": {
            "field": "job_count",
            "direction": "desc"
          }
        }
      ]
    },
    {
      "task_id": "T02",
      "title": "薪资元统计概况",
      "business_question": "基于数值字段“薪资元”，整体数据的平均值、中位数及极值是多少？以探索薪资水平的主要分布特征。",
      "priority": "P0",
      "priority_reason": "薪资是招聘数据的核心业务指标之一，了解其数值分布直接支持探索主要分布和差异的需求C01。若缺失，无法量化薪资集中趋势或离散程度。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "salary_avg"
              },
              {
                "function": "median",
                "field": "field_0004",
                "alias": "salary_median"
              },
              {
                "function": "min",
                "field": "field_0004",
                "alias": "salary_min"
              },
              {
                "function": "max",
                "field": "field_0004",
                "alias": "salary_max"
              }
            ]
          }
        }
      ]
    },
    {
      "task_id": "T03",
      "title": "学历与城市交叉分布",
      "business_question": "不同城市下，各学历要求的岗位数量分布如何？以探索人才要求在地域间的差异。",
      "priority": "P1",
      "priority_reason": "提供比单一维度更细致的差异视角，有助于深入理解“主要差异”这一目标，但非绝对核心，删除后仍可通过单维度分析回答基础问题。",
      "requirement_ids": [
        "C01"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "cross_count"
              }
            ],
            "dimensions": [
              "field_0001",
              "field_0005"
            ]
          }
        }
      ]
    }
  ]
}
